def replacement_backend():
    source = Path(__file__).resolve().with_name('replacement.py')
    spec = importlib.util.spec_from_file_location('fiat_replacement', source)
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def cmd_replacement_begin(args) -> None:
    backend = replacement_backend()
    try:
        request = backend.packet.load(backend.packet.read_regular(args.request))
        result = backend.begin(sys.modules[__name__], args.dir, request)
    except (backend.Refusal, backend.worker.Refusal, OSError, ValueError, KeyError, TypeError) as error:
        die('replacement-begin refused: ' + (str(error) if isinstance(error, backend.Refusal) else 'invalid-input'))
    print(json.dumps(result, sort_keys=True))


def cmd_replacement_resume(args) -> None:
    backend = replacement_backend()
    try:
        result = backend.resume(sys.modules[__name__], args.dir)
    except (backend.Refusal, backend.worker.Refusal, backend.adapter.Refusal,
            OSError, ValueError, KeyError, TypeError) as error:
        die('replacement-resume refused: ' + (str(error) if isinstance(error, backend.Refusal) else 'invalid-input'))
    print(json.dumps(result, sort_keys=True))

def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="hexctl", description=__doc__)
    p.add_argument("--dir", default=".", help="directory holding the state dir")
    sub = p.add_subparsers(dest="cmd", required=True)

    sp = sub.add_parser('replacement-begin', help='bind a fresh run to a complete replacement request')
    sp.add_argument('--request', required=True)
    sp.set_defaults(fn=cmd_replacement_begin)
    sp = sub.add_parser('replacement-resume', help='reconstruct, execute guards and recover pending admission')
    sp.set_defaults(fn=cmd_replacement_resume)

    sp = sub.add_parser("carryover-export", help="export inert cumulative evidence at exhausted audit")
    sp.add_argument("--request", required=True)
    sp.set_defaults(fn=cmd_carryover_export)
    sp = sub.add_parser("carryover-bind", help="bind a published attachment by exact packet readback")
    sp.add_argument("--request", required=True)
    sp.set_defaults(fn=cmd_carryover_bind)
    sp = sub.add_parser("carryover-validate", help="replay cumulative packet evidence without admission")
    sp.add_argument("--packet", required=True)
    sp.add_argument("--sha256", required=True)
    sp.set_defaults(fn=cmd_carryover_validate)

    sp = sub.add_parser("worker-exec", help="capture one declared native worker in retired scratch")
    sp.add_argument("--request", required=True)
    sp.set_defaults(fn=cmd_worker_exec)
    sp = sub.add_parser("worker-admit", help="promote reports from one pinned private capture")
    sp.add_argument("--receipt", required=True)
    sp.add_argument("--sha256", required=True)
    sp.set_defaults(fn=cmd_worker_admit)

    sp = sub.add_parser("init", help="start a run")
    sp.add_argument("--topic", required=True)
    sp.add_argument("--base", default="main")
    sp.add_argument(
        "--task-issue",
        dest="task_issue",
        help="task issue URL whose positive terminal issue number names the run",
    )
    sp.add_argument(
        "--run-branch",
        dest="run_branch",
        help="exact integration branch (default: topic slug, prefixed by task "
             "issue when supplied)",
    )
    sp.add_argument(
        "--frontier",
        help="EVOLUTION.md this run is meant to advance; the terminal receipt "
             "then refuses until it carries exactly one new valid row",
    )
    sp.add_argument(
        "--controller-currency-waiver",
        dest="controller_currency_waiver",
        metavar="REASON",
        help="proceed on a behind controller verdict, recording this reason "
             "in the run's evidence",
    )
    sp.set_defaults(fn=cmd_init)

    sp = sub.add_parser("status", help="show run state")
    shape = sp.add_mutually_exclusive_group()
    shape.add_argument("--json", action="store_true")
    shape.add_argument(
        "--field",
        metavar="PATH",
        help=(
            "print one dotted path out of the state --json would print, "
            "such as observation_run_id"
        ),
    )
    sp.set_defaults(fn=cmd_status)

    sp = sub.add_parser(
        "currency",
        help="report pin-versus-upstream currency for installed plugins",
    )
    sp.add_argument("--json", action="store_true")
    sp.set_defaults(fn=cmd_currency)

    sp = sub.add_parser(
        "issue-check",
        help="check one candidate or filed issue against the filing contract",
    )
    sp.add_argument("--body", help="path to the candidate issue body")
    sp.add_argument("--title", help="exact candidate issue title")
    sp.add_argument("--label", action="append", default=[],
                    help="candidate label; repeat for every label")
    sp.add_argument("--issue", help="canonical GitHub issue URL to read")
    sp.set_defaults(fn=cmd_issue_check)

    sp = sub.add_parser(
        "stale-bodies",
        help="report which open issues carry no status block (report-only)",
    )
    sp.add_argument("--bodies", required=True,
                    help="path to a JSON array of {number, title, body}")
    sp.add_argument("--json", action="store_true", help="emit the report as JSON")
    sp.set_defaults(fn=cmd_stale_bodies)

    sp = sub.add_parser("next", help="emit the single next action as JSON")
    sp.add_argument(
        "--brief-out",
        metavar="PATH",
        help=(
            "write the delegated brief to PATH and name it in brief_path, "
            "instead of printing its body"
        ),
    )
    sp.add_argument(
        "--task-handle",
        metavar="HANDLE",
        help=(
            "check HANDLE, the name of a delegate about to be continued, "
            "against task_identity.handle; a mismatch, a malformed HANDLE or "
            "a directive with no delegate exits 2 before the directive is "
            "printed"
        ),
    )
    sp.set_defaults(fn=cmd_next)

    sp = sub.add_parser(
        "run-exit",
        help="observe one registered Exit command for its consuming criterion",
    )
    sp.add_argument("--criterion", required=True)
    sp.set_defaults(fn=cmd_run_exit)

    sp = sub.add_parser(
        "retain-guard",
        help="retain one assigned detached-parent guard report and manifest",
    )
    sp.add_argument("--finding-id", dest="finding_id", required=True)
    sp.add_argument("--guard-commit", dest="guard_commit", required=True)
    sp.set_defaults(fn=cmd_retain_guard)

    sp = sub.add_parser(
        "verify-decision-assignments",
        help="replay one signed ADR assignment composition without writing state",
    )
    sp.add_argument("--report", required=True)
    sp.add_argument("--candidate", required=True)
    sp.add_argument("--candidate-ref", dest="candidate_ref", required=True)
    sp.set_defaults(fn=cmd_verify_decision_assignments)

    sp = sub.add_parser("record", help="store a named receipt")
    sp.add_argument("key")
    sp.add_argument("value")
    sp.set_defaults(fn=cmd_record)

    sp = sub.add_parser(
        "observe",
        help="bind one companion observation prefix or unavailable capture state",
    )
    sp.add_argument("--artifact")
    sp.add_argument(
        "--capture-status",
        required=True,
        choices=OBSERVATION_CAPTURE_STATUSES,
    )
    sp.add_argument(
        "--redaction-status",
        required=True,
        choices=OBSERVATION_REDACTION_STATUSES,
    )
    sp.add_argument("--reason-code")
    sp.set_defaults(fn=cmd_observe)

    sp = sub.add_parser("amend", help="receipt a bounded mid-run amendment")
    amend = sp.add_subparsers(dest="amend_subject", required=True)
    study = amend.add_parser("study", help="receipt one append-only study amendment")
    study.add_argument("--artifact", required=True)
    study.set_defaults(fn=cmd_amend_study)
    runbook = amend.add_parser(
        "runbook", help="receipt one append-only runbook amendment"
    )
    runbook.add_argument("--artifact", required=True)
    runbook.set_defaults(fn=cmd_amend_runbook)

    sp = sub.add_parser("config", help="get or set a config value")
    sp.add_argument("action", choices=["get", "set"])
    sp.add_argument("path")
    sp.add_argument("value", nargs="?")
    sp.set_defaults(fn=cmd_config)

    sp = sub.add_parser("done", help="receipt a completed phase")
    sp.add_argument("phase", choices=list(DONE_HANDLERS))
    sp.add_argument("--artifact")
    sp.add_argument("--skills")
    sp.add_argument("--steps-file", dest="steps_file")
    sp.add_argument("--branch")
    sp.add_argument("--commit")
    sp.add_argument("--base-commit", dest="base_commit")
    sp.add_argument("--revalidation")
    sp.add_argument("--accept-evolution-base", help="exact base SHA approved for cross-evolution version recovery")
    sp.add_argument("--recovery-authority", help="operator who authorised this exact evolution recovery")
    sp.add_argument("--decision-assignments", dest="decision_assignments")
    sp.add_argument("--supersede-sync", dest="supersede_sync")
    sp.add_argument(
        "--acknowledge-sync-path",
        dest="acknowledge_sync_paths",
        action="append",
        default=[],
    )
    sp.add_argument("--tests")
    sp.add_argument("--no-further-leads", dest="no_further_leads", action="store_true")
    sp.add_argument("--reason")
    sp.add_argument("--fixes-ref", dest="fixes_ref")
    sp.add_argument("--log")
    sp.add_argument("--files", type=int)
    sp.add_argument("--pr-url", dest="pr_url")
    sp.add_argument("--pr-base", dest="pr_base")
    sp.add_argument("--step", type=int)
    sp.add_argument("--head-commit", dest="head_commit")
    sp.add_argument("--merge-commit", dest="merge_commit")
    sp.add_argument("--closed-issue-url", dest="closed_issue_url")
    sp.set_defaults(fn=cmd_done)

    sp = sub.add_parser("audit-round", help="record one security round")
    sp.add_argument("--findings", type=int, required=True)
    sp.add_argument("--log")
    sp.add_argument("--audit-filter", dest="audit_filter")
    sp.add_argument("--fixes-commit", dest="fixes_commit")
    sp.add_argument(
        "--elenchus-verdict",
        dest="elenchus_verdict",
        choices=ELENCHUS_VERDICTS,
    )
    for lint in LINTS:
        sp.add_argument(
            f"--{lint}-exit",
            dest=f"{lint}_exit",
            type=int,
            help=f"the exit status {lint} returned; 0 is clean",
        )
    sp.set_defaults(fn=cmd_audit_round)

    sp = sub.add_parser("halt", help="stop the run with a reason")
    sp.add_argument("--reason")
    sp.set_defaults(fn=cmd_halt)

    sp = sub.add_parser("resume", help="clear a halt")
    sp.add_argument("--note")
    sp.set_defaults(fn=cmd_resume)

    sp = sub.add_parser(
        "checkpoint",
        help="identify, export, archive or restore portable controller state",
    )
    checkpoint = sp.add_subparsers(dest="checkpoint_action", required=True)
    identity = checkpoint.add_parser(
        "identity", help="print one verified semantic checkpoint identity"
    )
    identity.set_defaults(fn=cmd_checkpoint_identity)
    archive = checkpoint.add_parser(
        "archive", help="publish one outer checkpoint archive at this boundary"
    )
    archive.set_defaults(fn=cmd_checkpoint_archive)
    inspect = checkpoint.add_parser(
        "inspect", help="verify one outer checkpoint archive without extracting it"
    )
    inspect.add_argument("--archive", required=True, metavar="ZIP")
    inspect.add_argument("--sha256", required=True, metavar="SHA256")
    inspect.add_argument("--scratch", default=None, metavar="DIRECTORY")
    inspect.set_defaults(fn=cmd_checkpoint_inspect)
    export = checkpoint.add_parser(
        "export", help="write one deterministic controller capsule"
    )
    export.add_argument("--out", required=True, metavar="DIRECTORY")
    export.set_defaults(fn=cmd_checkpoint_export)
    restore = checkpoint.add_parser(
        "restore", help="relocate one verified controller capsule"
    )
    restore.add_argument("--from", dest="source", metavar="DIRECTORY")
    restore.add_argument("--manifest-sha256", metavar="SHA256")
    restore.add_argument(
        "--archive", metavar="ZIP", help="restore from one outer checkpoint archive"
    )
    restore.add_argument(
        "--sha256", metavar="SHA256", help="the archive's out-of-band outer SHA-256"
    )
    restore.set_defaults(fn=cmd_checkpoint_restore)

    sp = sub.add_parser(
        "reset", help="archive a completed or halted run and clear its active state"
    )
    sp.set_defaults(fn=cmd_reset)

    sp = sub.add_parser("verify", help="check ledger chain and state consistency")
    sp.add_argument(
        "--observations",
        action="store_true",
        help="also recompute every selected companion observation prefix",
    )
    sp.add_argument(
        "--check-filing-decision",
        action="store_true",
        dest="check_filing_decision",
        help=(
            "also re-read the task issue and report any divergence from the "
            "filing decision this run recorded; makes up to two network "
            "requests, which plain verify never does"
        ),
    )
    sp.set_defaults(fn=cmd_verify)

    return p


def main() -> None:
    args = build_parser().parse_args()
    if args.fn.__name__ in MUTATING:
        if args.fn.__name__ == "cmd_init":
            args._init_preflight = init_preflight(args)
        with held_lock(args.dir, args.fn.__name__):
            if args.fn.__name__ not in ("cmd_init", "cmd_halt", "cmd_resume", "cmd_reset", "cmd_amend_runbook"):
                recovering_no_known = args.fn.__name__ == "cmd_done" and args.phase == "inoculate"
                candidate_state = load_state(
                    args.dir, allow_pending_replacement=True,
                    allow_pending_amendment=True, allow_pending_resolution=True,
                    allow_pending_no_known=recovering_no_known,
                )
                gate_recovery_preflight(
                    args.dir, candidate_state, allow_source_drift=False,
                    allow_pending_no_known=recovering_no_known,
                )
            args.fn(args)
        return
    args.fn(args)


if __name__ == "__main__":
    main()
